import { spawn } from 'node:child_process';
import { once } from 'node:events';
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: ':memory:' },
  detached: true,
  stdio: ['ignore', 'pipe', 'inherit'],
});
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
    child.stdout.on('data', (chunk) => {
      const match = /listening on port (\\d+)/.exec(String(chunk));
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') {
    throw new Error('Health check failed');
  }
  console.log('npm start launch and health check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
}
EOF"

